import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as s,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Cursor tutorial","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/cursor/cursor.md","filePath":"products/ai-coding/cursor/cursor.md","lastUpdated":1787110548000}'),n={name:"products/ai-coding/cursor/cursor.md"};function o(r,e,l,d,h,c){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="cursor-tutorial" tabindex="-1">Cursor tutorial <a class="header-anchor" href="#cursor-tutorial" aria-label="Permalink to &quot;Cursor tutorial&quot;">​</a></h1><p>Cursor is a VS Code-based AI editor: Tab completions, <code>Cmd+K</code> on a selection, and <code>Cmd+I</code> for an agent that reads the repo, edits files, and runs commands.</p><blockquote><p>Parameters, shortcut tables, and the capability matrix: <a href="./cursor-cheatsheet.html">cheatsheet</a>. Definitions: <a href="./cursor-glossary.html">glossary</a>. Task recipes: <a href="./cursor-cookbook.html">cookbook</a>.</p><p>Docs track the 2026-08 tree at <a href="https://cursor.com/docs" target="_blank" rel="noreferrer">cursor.com/docs</a>. This page does not pin a patch version in headings.</p></blockquote><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>You can open a folder in VS Code, read a diff, and use the terminal</li><li>A machine that can sign in at <a href="https://cursor.com" target="_blank" rel="noreferrer">cursor.com</a></li><li>A <strong>git</strong> repo to practice on — agent edits hit disk immediately</li></ul><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>After this page you can:</p><ol><li>Finish “explain the repo → one small edit → review the diff” in five minutes</li><li>Tell Tab, Inline Edit, Agent, Plan, and Debug apart</li><li>Persist package-manager and folder conventions in <code>AGENTS.md</code> or one <code>.mdc</code> rule</li><li>Use <code>@</code> when you know the file, and skip it when you do not</li></ol><hr><h2 id="install-and-sign-in" tabindex="-1">Install and sign in <a class="header-anchor" href="#install-and-sign-in" aria-label="Permalink to &quot;Install and sign in&quot;">​</a></h2><ol><li>Install from <a href="https://cursor.com/downloads" target="_blank" rel="noreferrer">Downloads</a>.</li><li>Open the app and sign in.</li><li><strong>File → Open Folder</strong> on a git repo. Do not start in an empty window.</li></ol><p>Official path: <a href="https://cursor.com/docs/get-started/quickstart" target="_blank" rel="noreferrer">Quickstart</a>.</p><table tabindex="0"><thead><tr><th>Want</th><th>Shortcut</th></tr></thead><tbody><tr><td>Cursor settings (models, Tab, indexing)</td><td><code>Cmd+Shift+J</code> / <code>Ctrl+Shift+J</code></td></tr><tr><td>VS Code settings</td><td><code>Cmd+,</code> / <code>Ctrl+,</code></td></tr><tr><td>Command palette</td><td><code>Cmd+Shift+P</code> / <code>Ctrl+Shift+P</code></td></tr></tbody></table><p>Source: <a href="https://cursor.com/docs/reference/keyboard-shortcuts" target="_blank" rel="noreferrer">Keyboard Shortcuts</a>.</p><hr><h2 id="five-minute-first-example" tabindex="-1">Five-minute first example <a class="header-anchor" href="#five-minute-first-example" aria-label="Permalink to &quot;Five-minute first example&quot;">​</a></h2><p>Goal: prove the agent can read the repo and that you can review its diff. Steps follow the official Quickstart.</p><h3 id="_1-open-agent" tabindex="-1">1. Open Agent <a class="header-anchor" href="#_1-open-agent" aria-label="Permalink to &quot;1. Open Agent&quot;">​</a></h3><p><code>Cmd+I</code> / <code>Ctrl+I</code>. Both Quickstart and Agent Overview use this key.</p><h3 id="_2-ask-for-an-explanation-first" tabindex="-1">2. Ask for an explanation first <a class="header-anchor" href="#_2-ask-for-an-explanation-first" aria-label="Permalink to &quot;2. Ask for an explanation first&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Explain this codebase: stack, how directories are split, which files I should read first.</span></span>
<span class="line"><span>Do not modify any files.</span></span></code></pre></div><p>Cursor searches, reads, and summarizes. Official docs call this the fastest way into an unfamiliar repo.</p><h3 id="_3-make-one-low-risk-change" tabindex="-1">3. Make one low-risk change <a class="header-anchor" href="#_3-make-one-low-risk-change" aria-label="Permalink to &quot;3. Make one low-risk change&quot;">​</a></h3><p>Official first tasks: copy, small UI, comments. State the outcome.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Add one sentence to the Getting Started section of README.md:</span></span>
<span class="line"><span>This repo uses pnpm at the root. Do not run npm install.</span></span>
<span class="line"><span>Touch only README.md. Summarize the diff when done.</span></span></code></pre></div><p>TypeScript-only alternative:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Add formatISODate(date: Date): string to src/utils/formatDate.ts.</span></span>
<span class="line"><span>Return date.toISOString().slice(0, 10) (YYYY-MM-DD).</span></span>
<span class="line"><span>Export it. Do not touch other files. Tell me how to verify by hand.</span></span></code></pre></div><h3 id="_4-review-the-diff-and-run-checks-you-already-have" tabindex="-1">4. Review the diff and run checks you already have <a class="header-anchor" href="#_4-review-the-diff-and-run-checks-you-already-have" aria-label="Permalink to &quot;4. Review the diff and run checks you already have&quot;">​</a></h3><ol><li>Confirm the diff is only the file you allowed</li><li>Ask it to run <strong>existing</strong> checks — do not invent script names:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Run the typecheck and lint this project already uses. Do not add config files.</span></span></code></pre></div><ol start="3"><li>Run the same command yourself (<code>pnpm typecheck</code>, etc.)</li></ol><h3 id="_5-use-plan-mode-for-bigger-work" tabindex="-1">5. Use Plan Mode for bigger work <a class="header-anchor" href="#_5-use-plan-mode-for-bigger-work" aria-label="Permalink to &quot;5. Use Plan Mode for bigger work&quot;">​</a></h3><p><code>Shift+Tab</code> in the agent input. Official sequence:</p><ol><li>Research the repo</li><li>Ask clarifying questions</li><li>Write an editable plan</li><li><strong>Wait for approval before coding</strong></li></ol><p>Plans default to your home directory. <strong>Save to workspace</strong> stores them in the repo (the official blog names <code>.cursor/plans/</code>).</p><hr><h2 id="four-modes" tabindex="-1">Four modes <a class="header-anchor" href="#four-modes" aria-label="Permalink to &quot;Four modes&quot;">​</a></h2><p>Same agent, different constraints. <code>Cmd+.</code> / <code>Ctrl+.</code> opens the mode menu. <code>Shift+Tab</code> also rotates Plan.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Does</th><th>Use when</th></tr></thead><tbody><tr><td><strong>Agent</strong></td><td>Search, edit, terminal</td><td>Clear implementation work</td></tr><tr><td><strong>Ask</strong></td><td>Read-only Q&amp;A (changelog: Ask has search tools; the <code>@Codebase</code> tool was removed)</td><td>Understand first</td></tr><tr><td><strong>Plan</strong></td><td>Research, questions, editable plan</td><td>Many files or fuzzy requirements</td></tr><tr><td><strong>Debug</strong></td><td>Hypotheses → logs → you reproduce → evidence-based fix</td><td>Reproducible, cause unknown</td></tr></tbody></table><p>Pages: <a href="https://cursor.com/docs/agent/overview" target="_blank" rel="noreferrer">Overview</a>, <a href="https://cursor.com/docs/agent/plan-mode" target="_blank" rel="noreferrer">Plan Mode</a>, <a href="https://cursor.com/docs/agent/debug-mode" target="_blank" rel="noreferrer">Debug Mode</a>. Ask appears in the <a href="https://cursor.com/changelog" target="_blank" rel="noreferrer">changelog</a>; there is no standalone Modes page in the 2026-08 nav.</p><h3 id="three-agent-habits" tabindex="-1">Three Agent habits <a class="header-anchor" href="#three-agent-habits" aria-label="Permalink to &quot;Three Agent habits&quot;">​</a></h3><ol><li><strong>Checkpoints</strong> — snapshots before big edits. Restore instead of hand-undoing.</li><li><strong>Queue</strong> — <code>Enter</code> queues while the agent works; <code>Cmd+Enter</code> / <code>Ctrl+Enter</code> injects into the current turn.</li><li><strong>New chat</strong> — new task, repeated mistakes, or a finished unit of work. Pull old context with <code>@Chats</code>.</li></ol><p>Sources: <a href="https://cursor.com/docs/agent/overview" target="_blank" rel="noreferrer">Overview</a>, <a href="https://cursor.com/docs/agent/prompting" target="_blank" rel="noreferrer">Prompting</a>, <a href="https://cursor.com/blog/agent-best-practices" target="_blank" rel="noreferrer">agent-best-practices</a>.</p><hr><h2 id="tab-and-inline-edit" tabindex="-1">Tab and Inline Edit <a class="header-anchor" href="#tab-and-inline-edit" aria-label="Permalink to &quot;Tab and Inline Edit&quot;">​</a></h2><h3 id="tab" tabindex="-1">Tab <a class="header-anchor" href="#tab" aria-label="Permalink to &quot;Tab&quot;">​</a></h3><p><a href="https://cursor.com/docs/tab/overview" target="_blank" rel="noreferrer">Tab</a> is a completion model, not the agent.</p><ul><li>New text: ghost text. Edits: a diff popup</li><li><code>Tab</code> accept, <code>Esc</code> reject, <code>Cmd+→</code> / <code>Ctrl+→</code> word-by-word</li><li>After an accept, <code>Tab</code> can jump to the next predicted location</li><li>TypeScript / Python can auto-import</li><li>Status bar: snooze, disable globally, or disable by extension</li></ul><p>Do <strong>not</strong> start an Agent turn to change three lines under the caret.</p><h3 id="inline-edit" tabindex="-1">Inline Edit <a class="header-anchor" href="#inline-edit" aria-label="Permalink to &quot;Inline Edit&quot;">​</a></h3><p><a href="https://cursor.com/docs/inline-edit/overview" target="_blank" rel="noreferrer">Inline Edit</a>: <code>Cmd+K</code> / <code>Ctrl+K</code>.</p><ul><li>With a selection: edit that range</li><li>Without: generate at the cursor, using surrounding code</li><li><code>Opt+Enter</code> / <code>Alt+Enter</code>: Quick Question; say <code>do it</code> to apply</li><li>Multi-file: send the selection to Chat with <code>Cmd+L</code> / <code>Ctrl+L</code></li></ul><hr><h2 id="project-context" tabindex="-1">Project context <a class="header-anchor" href="#project-context" aria-label="Permalink to &quot;Project context&quot;">​</a></h2><p>Models do not remember preferences across completions. Persist them with Rules / <code>AGENTS.md</code>. Mechanism: <a href="./cursor-glossary.html#rules">glossary · Rules</a>.</p><h3 id="minimal-agents-md" tabindex="-1">Minimal <code>AGENTS.md</code> <a class="header-anchor" href="#minimal-agents-md" aria-label="Permalink to &quot;Minimal \`AGENTS.md\`&quot;">​</a></h3><p>Official position: a simple alternative without metadata. Subdirectories may add their own.</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Agent notes</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Package manager is pnpm. Never </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`npm install\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> or yarn.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Source lives in </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`src/\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">. Tests are </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`src/**/*.test.ts\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> After edits run </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`pnpm typecheck\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> and </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`pnpm test\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> UI components: follow </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`src/components/Button.tsx\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">. Do not paste that file into rules.</span></span></code></pre></div><h3 id="one-file-scoped-rule" tabindex="-1">One file-scoped rule <a class="header-anchor" href="#one-file-scoped-rule" aria-label="Permalink to &quot;One file-scoped rule&quot;">​</a></h3><p>Files under <code>.cursor/rules</code> must be <strong><code>.mdc</code></strong>. A plain <code>.md</code> is ignored.</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">TypeScript module conventions</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">globs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;**/*.ts,**/*.tsx&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">alwaysApply</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ES modules only (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`import\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> / </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`export\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">). No </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`require\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Prefer named exports.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Canonical structure: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`src/components/Button.tsx\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span></code></pre></div><p>Trigger table: <a href="./cursor-cheatsheet.html#rules-frontmatter">cheatsheet · Rules</a>. Create with <code>/create-rule</code>.</p><p>Official limit: <strong>under 500 lines</strong> per rule. Split large ones. Put style in the linter, not in a pasted style guide.</p><hr><h2 id="how-to-give-context" tabindex="-1">How to give context <a class="header-anchor" href="#how-to-give-context" aria-label="Permalink to &quot;How to give context&quot;">​</a></h2><p>Source: <a href="https://cursor.com/docs/agent/prompting" target="_blank" rel="noreferrer">Prompting</a>.</p><table tabindex="0"><thead><tr><th>Mention</th><th>Meaning</th></tr></thead><tbody><tr><td><code>@auth.ts</code> / <code>@src/components/</code></td><td>File or folder. Type <code>/</code> after a folder to go deeper</td></tr><tr><td><code>@Terminals</code></td><td>Terminal output</td></tr><tr><td><code>@Chats</code></td><td>A previous conversation</td></tr><tr><td><code>@Commit (Diff of Working State)</code></td><td>Uncommitted diff</td></tr><tr><td><code>@Branch (Diff with Main)</code></td><td>Diff against main</td></tr><tr><td><code>@Browser</code></td><td>Built-in browser</td></tr></tbody></table><p><strong>Tag a file when you know it. Otherwise let the agent search.</strong> Irrelevant <code>@</code> files dilute the prompt.</p><p>Images: drag in, or paste with <code>Cmd+V</code> / <code>Ctrl+V</code>.</p><p>Models: picker on the input, or <code>Cmd+/</code> / <code>Ctrl+/</code>. You can switch mid-thread. Catalog: <a href="https://cursor.com/docs/models-and-pricing" target="_blank" rel="noreferrer">Models &amp; Pricing</a>.</p><hr><h2 id="default-workflow" tabindex="-1">Default workflow <a class="header-anchor" href="#default-workflow" aria-label="Permalink to &quot;Default workflow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Open the repo</span></span>
<span class="line"><span>  → New chat: “how does this repo work”</span></span>
<span class="line"><span>  → Write AGENTS.md / one rule (only what you already corrected twice)</span></span>
<span class="line"><span>  → Small edit: Tab or Cmd+K</span></span>
<span class="line"><span>  → Medium: Agent with an explicit check command and a do-not-touch list</span></span>
<span class="line"><span>  → Large: Plan → edit the plan → approve → implement → existing checks</span></span>
<span class="line"><span>  → Wrong turn: Restore Checkpoint, or refine the plan and rerun</span></span>
<span class="line"><span>  → PR: Bugbot or /review-bugbot</span></span>
<span class="line"><span>  → Away / parallel: Cloud Agents. Terminal / CI: \`agent\`</span></span></code></pre></div><p>Be specific. Official contrast: “add tests for auth.ts” vs “write the logout edge case for <code>auth.ts</code> using patterns in <code>__tests__/</code>, no mocks.”</p><hr><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pitfall</th><th>Do this</th></tr></thead><tbody><tr><td>First prompt is “refactor the directory”</td><td>Explain, then one file, then Plan</td></tr><tr><td>Agent for three local lines</td><td>Tab or <code>Cmd+K</code></td></tr><tr><td>Single <code>.cursorrules</code> as the only source of truth</td><td><code>.cursor/rules/*.mdc</code> or <code>AGENTS.md</code></td></tr><tr><td>Paste a whole component into a rule</td><td>Point at <code>src/components/Button.tsx</code></td></tr><tr><td>Treat Bugbot as a runtime debugger</td><td>Debug Mode locally; Bugbot on the PR</td></tr><tr><td>Continue a long chat after changing topics</td><td>New chat + <code>@Chats</code></td></tr><tr><td>Trust “tests passed” in the transcript</td><td>Re-run the command yourself</td></tr><tr><td>Agent in a folder with no git</td><td><code>git init</code> or open a real repo</td></tr></tbody></table><p>Community signal (not an official guarantee): some users report Plan still writing code (<a href="https://forum.cursor.com/t/plan-mode-is-not-respected-by-the-agent/151802" target="_blank" rel="noreferrer">thread</a>). If that happens: Stop, Restore, and write “do not edit files until I reply APPROVE” into the plan.</p><hr><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ol><li><a href="./cursor-cookbook.html">Cookbook</a> — bugs, features, Rules, Bugbot, Cloud, CLI, MCP</li><li><a href="./design-mode.html">Design Mode</a> · <a href="./cloud-agents.html">Cloud Agents</a> · <a href="./cursor-cli.html">Cursor CLI</a></li><li><a href="./origin.html">Origin</a> · <a href="./security-agents.html">Security Agents</a> · <a href="./pr-routing.html">PR Routing</a> · <a href="./cursor-sdk.html">SDK</a></li><li><a href="./cursor-cheatsheet.html">Cheatsheet</a></li><li><a href="./cursor-glossary.html">Glossary</a></li><li><a href="./">Learning map</a> — editor vs CLI vs Cloud vs Origin vs SDK</li><li>Official: <a href="https://cursor.com/docs/get-started/quickstart" target="_blank" rel="noreferrer">Quickstart</a>, <a href="https://cursor.com/blog/agent-best-practices" target="_blank" rel="noreferrer">Agent best practices</a></li></ol>`,81)])])}const f=t(n,[["render",o]]);export{m as __pageData,f as default};
